describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent discounts from original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child discounts to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0 + 100 = 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("can exceed subtotal (caller clamps)", () => {
      // Two 60% discounts on 1000 = 600 + 600 = 1200 (exceeds 1000)
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(60),
          new PercentageDiscountPolicy(60),
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // 10% of 1000 = 100, then 10% of 900 = 90 → total = 190
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new PercentageDiscountPolicy(10),
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering affects the result in chain mode", () => {
      // Fixed 500 first: remaining 500, then 10% of 500 = 50 → total 550
      const fixedFirst = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(500),
          new PercentageDiscountPolicy(10),
        ],
        "chain",
      );
      // 10% of 1000 = 100 first: remaining 900, then fixed 500 → total 600
      const percentFirst = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      expect(fixedFirst.computeDiscountCents(1000)).toBe(550);
      expect(percentFirst.computeDiscountCents(1000)).toBe(600);
    });

    it("cannot exceed subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(800),
          new FixedAmountDiscountPolicy(800),
        ],
        "chain",
      );
      // 800 from 1000, remaining 200, then min(800, 200)=200 → total 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("clamps negative child discounts to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      // negative clamped to 0, then 300 from 1000 → 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  describe("defaults to sum mode", () => {
    it("uses sum when mode is not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });
});

