    expect(() => cart.updateQuantity("unknown", 1)).toThrow(
      "not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity(widget.id, -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity(widget.id, 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(gadget, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart — totals with defaults", () => {
  it("empty cart totals are all zero", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("subtotal is sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 3); // 3 * 1000 = 3000
    cart.add(gadget, 1); // 1 * 2000 = 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(5000);
    // Default: no discount, no tax, free shipping
    expect(totals.totalCents).toBe(5000);
  });
});

describe("Cart — pricing pipeline composition", () => {
  it("applies discount → tax on discounted subtotal → shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10), // 10% off
      taxCalculator: new RegionalTaxCalculator({ US: 0.1 }), // 10% tax
      shippingCalculator: new FlatShippingCalculator(500), // $5 flat
      region: "US",
    });
    cart.add(widget, 10); // subtotal = 10000

    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(10000);
    expect(totals.discountCents).toBe(1000); // 10% of 10000
    // Tax on discounted subtotal: 10% of 9000 = 900
    expect(totals.taxCents).toBe(900);
    expect(totals.shippingCents).toBe(500);
    // total = 9000 + 900 + 500 = 10400
    expect(totals.totalCents).toBe(10400);
  });

  it("clamps discount to subtotal (policy returns more)", () => {
    const overPolicy: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overPolicy });
    cart.add(widget, 1); // subtotal = 1000

    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negPolicy: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negPolicy });
    cart.add(widget, 1); // subtotal = 1000

    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(widget, 1);

    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShip: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShip });
    cart.add(widget, 1);

    expect(cart.totals().shippingCents).toBe(0);
  });

  it("shipping receives discounted subtotal", () => {
    const spyShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(500),
      shippingCalculator: spyShipping,
    });
    cart.add(widget, 1); // subtotal 1000, discount 500
    cart.totals();

    expect(spyShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      500, // discounted subtotal
    );
  });

  it("uses default region US when not specified", () => {
    const spyTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: spyTax });
    cart.add(widget, 1);
    cart.totals();

    expect(spyTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("uses custom region", () => {
    const spyTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: spyTax, region: "FR" });
    cart.add(widget, 1);
    cart.totals();

    expect(spyTax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

