  describe("with AsyncTaxRateProvider", () => {
    it("uses async tax computation in checkout", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
      });
      cart.add(widget, 10); // subtotal 10000

      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({ asyncTaxProvider: provider });

      // Discount: 10% of 10000 = 1000
      expect(result.totals.discountCents).toBe(1000);
