import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2000 };
const heavy: Product = {
  id: "h1",
  name: "Heavy",
  unitPriceCents: 500,
  weightGrams: 3000,
};

describe("Cart — line management", () => {
  it("starts empty", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities when adding same product twice", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
  });

  it("tracks multiple products separately", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 2);
    expect(cart.itemCount).toBe(3);
    expect(cart.snapshot()).toHaveLength(2);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(cart.remove(widget.id)).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updates quantity of existing product", () => {
    const cart = new Cart();
    cart.add(widget, 5);
    cart.updateQuantity(widget.id, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("updateQuantity with 0 removes the product", () => {
    const cart = new Cart();
    cart.add(widget, 5);
    cart.updateQuantity(widget.id, 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 1)).toThrow(
      "not in the cart",
    );
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity(widget.id, -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity(widget.id, 1.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(gadget, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart — totals with defaults", () => {
  it("empty cart totals are all zero", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("subtotal is sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 3); // 3 * 1000 = 3000
    cart.add(gadget, 1); // 1 * 2000 = 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(5000);
    // Default: no discount, no tax, free shipping
    expect(totals.totalCents).toBe(5000);
  });
});

describe("Cart — pricing pipeline composition", () => {
  it("applies discount → tax on discounted subtotal → shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10), // 10% off
      taxCalculator: new RegionalTaxCalculator({ US: 0.1 }), // 10% tax
      shippingCalculator: new FlatShippingCalculator(500), // $5 flat
      region: "US",
    });
    cart.add(widget, 10); // subtotal = 10000

    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(10000);
    expect(totals.discountCents).toBe(1000); // 10% of 10000
    // Tax on discounted subtotal: 10% of 9000 = 900
    expect(totals.taxCents).toBe(900);
    expect(totals.shippingCents).toBe(500);
    // total = 9000 + 900 + 500 = 10400
    expect(totals.totalCents).toBe(10400);
  });

  it("clamps discount to subtotal (policy returns more)", () => {
    const overPolicy: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overPolicy });
    cart.add(widget, 1); // subtotal = 1000

    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negPolicy: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negPolicy });
    cart.add(widget, 1); // subtotal = 1000

    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(widget, 1);

    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShip: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShip });
    cart.add(widget, 1);

    expect(cart.totals().shippingCents).toBe(0);
  });

  it("shipping receives discounted subtotal", () => {
    const spyShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(500),
      shippingCalculator: spyShipping,
    });
    cart.add(widget, 1); // subtotal 1000, discount 500
    cart.totals();

    expect(spyShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      500, // discounted subtotal
    );
  });

  it("uses default region US when not specified", () => {
    const spyTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: spyTax });
    cart.add(widget, 1);
    cart.totals();

    expect(spyTax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("uses custom region", () => {
    const spyTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: spyTax, region: "FR" });
    cart.add(widget, 1);
    cart.totals();

    expect(spyTax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

describe("Cart — checkout()", () => {
  it("returns totals and lines for simple checkout", async () => {
    const cart = new Cart();
    cart.add(widget, 2);

    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.quantity).toBe(2);
  });

  describe("with PriceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(widget, 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });

      expect(result.totals.subtotalCents).toBe(1500);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    });

    it("propagates fetcher errors", async () => {
      const cart = new Cart();
      cart.add(widget, 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price error")),
      };
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "price error",
      );
    });
  });

  describe("with InventoryChecker", () => {
    it("succeeds when all items are available", async () => {
      const cart = new Cart();
      cart.add(widget, 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(widget, 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "out of stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe(widget.id);
        expect(err.requested).toBe(2);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(widget, 5);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe(widget.id);
        expect(err.requested).toBe(5);
        expect(err.available).toBe(3);
      }
    });

    it("uses default message when reason not provided", async () => {
      const cart = new Cart();
      cart.add(widget, 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        const err = e as InventoryError;
        expect(err.message).toContain("insufficient stock");
        expect(err.message).toContain(widget.id);
      }
    });

    it("checks inventory for each line, first denial wins", async () => {
      const cart = new Cart();
      cart.add(widget, 1);
      cart.add(gadget, 1);

      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true })
          .mockResolvedValueOnce({ available: false, reason: "sold out" }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe(gadget.id);
      }
    });
  });

  describe("with AsyncTaxRateProvider", () => {
    it("uses async tax computation in checkout", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(500),
      });
      cart.add(widget, 10); // subtotal 10000

      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({ asyncTaxProvider: provider });

      // Discount: 10% of 10000 = 1000
      expect(result.totals.discountCents).toBe(1000);
      // Tax: 8% of 9000 = 720
      expect(result.totals.taxCents).toBe(720);
      expect(result.totals.shippingCents).toBe(500);
      // Total: 9000 + 720 + 500 = 10220
      expect(result.totals.totalCents).toBe(10220);
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart();
      cart.add(widget, 1);

      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };

      await expect(
        cart.checkout({ asyncTaxProvider: provider }),
      ).rejects.toThrow("rate service down");
    });
  });

  describe("with all collaborators", () => {
    it("runs full pipeline: refresh → inventory → async tax", async () => {
      const cart = new Cart({
        discountPolicy: new FixedAmountDiscountPolicy(200),
        shippingCalculator: new FreeShippingCalculator(),
      });
      cart.add(widget, 2); // original subtotal 2000

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });

      // Refreshed subtotal: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // Discount: fixed 200
      expect(result.totals.discountCents).toBe(200);
      // Tax: 10% of (2400 - 200) = 10% of 2200 = 220
      expect(result.totals.taxCents).toBe(220);
      expect(result.totals.shippingCents).toBe(0);
      // Total: 2200 + 220 + 0 = 2420
      expect(result.totals.totalCents).toBe(2420);

      expect(fetcher.fetchPriceCents).toHaveBeenCalledTimes(1);
      expect(checker.check).toHaveBeenCalledTimes(1);
    });
  });
});

